def z_function(input_string):
    n = len(input_string)
    z = [0] * n
    l = r = 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and input_string[z[i]] == input_string[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def lcp_length(s, t):
    return max([z[min(i, len(s)-i)] for i in range(1, min(len(s), len(t))+1)])

def compute_zebors(s):
    zs = z_function(s)
    result = 0
    for z in zs:
        result += z
    return result

