from collections import deque

def find_subsequence_length(arr, length):
    max_streaks = [1] * length
    next_max_index = [None] * length

    for i in range(1, length):
        min_value = arr[0]
        min_index = 0
        for j in range(1, length):
            if arr[j] < min_value:
                min_value = arr[j]
                min_index = j

        for j in range(min_index, length):
            if arr[j] >= min_value and next_max_index[j] is None:
                next_max_index[j] = min_index
            elif arr[j] < min_value and next_max_index[j] is not None:
                max_streaks[j] += max_streaks[next_max_index[j]]
                next_max_index[j] = None

        if next_max_index[min_index] is not None:
            min_value = arr[next_max_index[min_index]]
            min_index = next_max_index[min_index]

    return max(max_streaks)

