import sys

def find_password(input_string):
    start, end = "", ""

    for i in range(1, len(input_string) // 2 + 1):
        # start from i and end at len - i
        prefix = input_string[:i]
        suffix = input_string[len(input_string) - i:]
        # middle is the rest
        middle = input_string[i:len(input_string) - i]
        if len(prefix) == len(middle) and len(middle) <= len(suffix) and middle == middle[::-1]:
            start = input_string[0:i]
            end = input_string[-(len(input_string) // 2):]

    if not start:
        start = input_string[0:i-1]
        end = input_string[len(input_string) - (len(input_string) // 2) + 1:]

    return start, end, middle[::-1]

