def calculate_plans(n, m, storehouse):
    mod = 10**9 + 7
    pref = [[0] * (m+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(m):
            if storehouse[i][j] == 'x':
                pref[i+1][j+1] = pref[i+1][j]+1
                pref[i+1][j+1] %= mod
            else:
                pref[i+1][j+1] = pref[i][j+1]+1

    plans = 0
    for i in range(n+1):
        if pref[i][m] < i:
            for j in range(m):
                if pref[i][m]>pref[i][j] and pref[i][j]>i:
                    plans += 1
    return plans % mod

