import math

def calculate_beauty(N, A):
    val = 0
    for i in range(1, N):
        for j in range(i + 1, N):
            if A[i] < A[j]:
                val += 1
            else:
                val -= 1
    return val

def expected_beauty(N, edges):
    # Trivial case where there are no edges, hence beauty is 1
    if N == 1:
        return 1.0

    # Precompute prefix sums to quickly calculate sum of elements for a portion of the array
    prefix_sums = [0]
    for i in range(N - 1):
        prefix_sums.append(prefix_sums[-1] + A[i + 1])

    # Calculate the expected value
    expected_beauty = 0.0
    for start in range(1, N - 1):
        end = start + N - 1
        beauty_sum = prefix_sums[end] - prefix_sums[start]
        expected_beauty += (1.0 / N * beauty_sum)

    return expected_beauty + calculate_beauty(N, A)

