import math

def max_correct_set(n, x, y):
    if x == 1 and y == 2:
        return math.ceil(n / 3)
    elif x == 2 and y == 4:
        if n <= 8:
            return 3
        else:
            return 3 + (n - 8) // 5
    elif x == 3 and y == 1:
        if n <= 2:
            return 1
        else:
            if n <= 5:
                return 3
            elif n <= 8:
                return 4
            else:
                return 4 + (n - 8) // 5
    else:
        raise ValueError("Invalid inputs for x and y")

