import math

def beauty_function(N, A):
    val = 0
    for i in range(1, N):
        for j in range(i + 1, N):
            if A[i] < A[j]:
                val += 1
            else:
                val -= 1
    return val

def expected_beauty(N, edges):
    result = 0
    for i in range(N):
        for edge in edges:
            if edge[0] == i + 1:
                for neib in edge[1]:
                    result += beauty_function(N, A[:neib][::-1])
            elif edge[1] == i + 1:
                for neib in edge[0]:
                    result += beauty_function(N, A[:neib][::-1])
    return result / (math.factorial(N - 1) / math.factorial(2))

