from math import comb

def count_suitable_plans(n, m, matrix):
    mod = 10**9 + 7

    import numpy as np

    # Convert the list of characters to a numpy array for easier manipulation
    grid = np.array(matrix)

    ways = 1
    full_plans = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'x':
                left_side = 0
                right_side = 0
                up_side = 0
                down_side = 0

                # Count the number of guards to the right for each cell
                for k in range(j+1, m):
                    if grid[i][k] == 'x':
                        right_side += 1
                        break
                    if grid[i][k] == '.':
                        right_side += 1

                # Count the number of guards below for each cell
                for k in range(i+1, n):
                    if grid[k][j] == 'x':
                        down_side += 1
                        break
                    if grid[k][j] == '.':
                        down_side += 1

                # Count the number of turns made to the right and right-shifted blocks
                left_turns = 0
                right_turns = 0
                turn_blocks = 0
                total_turns = 0

                for k in range(j, m):
                    if grid[i][k] == '.' and grid[k][j] == '.':
                        if grid[i][k] == 'x':
                            right_turns += 1
                            if right_turns == left_turns:
                                total_turns += 2
                            else:
                                total_turns += 1
                        else:
                            left_turns += 1
                            if left_turns + turn_blocks != right_turns:
                                total_turns += 1

                if left_turns == right_turns:
                    turn_blocks += 1

                if left_side == 1 and not right_side == 0 and not down_side == 0 and not up_side == 0:
                    total_turns = turn_blocks
                    full_plans += 1

                if total_turns % 2 != left_side % 2:
                    full_plans += 1

                if full_plans == 0:
                    ways *= comb(n-1, i)
                    ways %= mod
                    left_side = 0
                    right_side = 0
                    up_side = 0
                    down_side = 0

    return ways

