def factorial_mod(n, mod):
    if n <= 1:
        return 1
    else:
        return (n * (factorial_mod(n-1, mod) % mod)) % mod

def mod_inverse(a, m):
    gcd, x, y = extended_euclidean_algorithm(a, m)
    if gcd == 1:
        return x % m
    else:
        return -1

def extended_euclidean_algorithm(a, b):
    if b == 0:
        return (a, 1, 0)
    else:
        g, y, x = extended_euclidean_algorithm(b, a % b)
        return (g, x - (a // b) * y, y)

def nCr(n, r, mod):
    if r > n or r < 0:
        return 0
    elif n == r or r == 0:
        return 1
    else:
        return (factorial_mod(n, mod) // (factorial_mod(r, mod) * factorial_mod(n - r, mod))) % mod

def num_good_trees(n, m, weights):
    if n == 1:
        count = []
        for weight in weights:
            count.append(1)
        return count
    else:
        mod = 998244353
        sum_weights = sum(weights)
        ans = []

        if any(sum(i) > m for i in weights):
            return ans  # No valid trees if any weight exceeds m

        for i in weights:
            if sum_weights - i <= m:
                ans.append(nCr((sum_weights - i) - 1, n - 1, mod) * mod_inverse(factorial_mod(n - 1, mod), mod)) % mod

        return ans

