# Calculate the number of good vertex-weighted rooted binary trees for a given weight
def good_trees(tree_count: int, weight_sum: int, match_count: int, n: int, m: int) -> int:
    if n != m:
        raise ValueError("n cannot be different from m")
    if weight_sum < 0:
        raise ValueError("Weight sum cannot be negative")
    if weight_sum < n:
        return 0
    return pow(match_count, (2**n - weight_sum) // 2, 998244353) * pow(n, (2**n - weight_sum + n) // 2, 998244353) * comb(weight_sum, n) % 998244353

def process_input() -> (int, int, List[int]):
    n, m = map(int, input().strip().split())
    trial_cases = list(map(int, input().strip().split()))
    return n, m, trial_cases

def process_output(trial_cases: List[int]) -> None:
    for s in trial_cases:
        print(good_trees(n, s, match_count, n, m))

if __name__ == "__main__":
    _, _, trial_cases = process_input()
