from collections import defaultdict

def find_root_with_max_subtrees(graph):
    discovered = set()
    results = []
    for idx, root in enumerate(graph, 1):
        stack = [(root, 1)]
        while stack:
            node, children = stack.pop(0)
            if node == idx:
                results.append((idx, children))
            for neighbor in graph[node]:
                if neighbor not in discovered:
                    # If we're at an unseen node, add it to the stack
                    stack.append((neighbor, children + 1))
                    discovered.add(neighbor)
    return max(results, key=lambda x: x[1], default=(0, 0))

