    dp = [[sys.maxsize] * m for _ in range(n)]

    dp[0][0] = -(int(important_squares[0][0]) - int(important_squares[1][0])) * flowers[0][0]

    for square in important_squares:
        for i, j in zip(*map(int, square.split())):  # Split tuple by spaces, each will give x, y
            dp[i][j] = -(int(square[0]) - int(square[2])) * flowers[i][j]

    visited = set()
    queue = []

    for i in range(n):
        for j in range(m):
            if (i, j) in important_squares:
                visited.add((i, j))
                queue.append((i, j))

    while queue:
        i, j = queue.pop(0)
        if i - 1 > -1:
            if (i-1, j) not in visited:
                parent = (i, j)
                dp[i][j] += dp[i-1][j]
                visited.add((i-1, j))
                queue.append((i-1, j))
        if i + 1 < n:
            if (i+1, j) not in visited:
                parent = (i, j)
                dp[i][j] += dp[i+1][j]
                visited.add((i+1, j))
                queue.append((i+1, j))
        if j - 1 > -1:
            if (i, j-1) not in visited:
                parent = (i, j)
                dp[i][j] += dp[i][j-1]
                visited.add((i, j-1))
                queue.append((i, j-1))
        if j + 1 < m:
            if (i, j+1) not in visited:
                parent = (i, j)
                dp[i][j] += dp[i][j+1]
                visited.add((i, j+1))
                queue.append((i, j+1))

    dead_flowers = sum(flowers[i][j] for column in dp for i, j in column)
    return dead_flowers


