def bfs(rooms, distances, l):
    n = len(rooms)
    # Initialize the distances array with an infinity until calculate
    for i in range(n):
        distances[i] = 1e11

    # Assign the distance of the leaves to the ground to l before calculate
    for leaf in [i for (i, _, v) in rooms if v == 1]:
        distances[leaf] = l
        q = queue.Queue()
        q.put((0, leaf))
        while not q.empty():
            cur, node = q.get()
            for next_node in downhill(rooms, node):
                distance_to_next = distances[node] - rooms[node][next_node] + cur + 2 * rooms[node][next_node]
                if distance_to_next < distances[next_node]:
                    distances[next_node] = distance_to_next
                    q.put((distance_to_next, next_node))

    # Over F region to update the positions in distance array and calculate the time
    eids = 0
    for i in range(n):
        if distances[i] < distances[eids]:
            eids = i

    if distances[eids] < distances[max(eids)]:
        return distances[eids]
    elif distances[eids] > distances[min(eids)]:
        return distances[min(eids)]
    else:
        l_2nd = distances[0] - distances[min(eids)]
        dist_eids = distances[eids] - distances[min(eids)]
        time = min(2 * l_2nd, dist_eids)
        for i in range(n):
            if i != eids:
                time = max(time, distances[eids] - distances[i] + 2 * rooms[eids][i])
        if time > min(perimeter_max(), perimeter_min()):
            return distances[eids]
        else:
            return perimeter_max()

def downhill(rooms, from_room):
    n = len(rooms)
    ret = []
    while from_room not in ret and from_room < n:
        ret.append(from_room)
        for direction in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nxt_room = from_room + rooms[from_room][direction]
            if nxt_room < n and rooms[nxt_room][from_room] == 0 and nxt_room not in ret:
                ret.append(nxt_room)
                break

    for i in range(len(ret) - 1):
        for j in range(i + 1, len(ret)):
            edfw = direction_sum(rooms, ret[i], ret[j])
            if edfw == 0:
                continue
            ret = ret[:i] + [(ret[i], j)] + ret[j + 1:]

    return ret

def direction_sum(rooms, from_room, to_room):
    mn_obj = float('inf')
    edfw_v = float('inf')
    for d in range(4):
        edfw = rooms[from_room][(d + to_room) % 4] - rooms[to_room][(d + from_room) % 4]
        if edfw < edfw_v or (edfw == edfw_v and rooms[from_room][d] < rooms[to_room][d]):
            edfw_v, mn_obj = edfw, d

    return edfw_v if mn_obj != float('inf') else 0;

def perimeter(rooms, from_room):
    v_obj = []
    for i in range(4):
        v = rooms[from_room][i]
        if rooms[from_room][i] == 0:
            for j in range(i + 1, 4):
