    def find_components():
        components = defaultdict(list)
        visited = [False] * n
        comp_count = 0

        def dfs(u):
            visited[u] = True
            components[comp_count].append(u)
            for nxt in graph[u]:
                if not visited[nxt]:
                    dfs(nxt)

        for u in range(n):
            if not visited[u]:
                dfs(u)
                comp_count += 1

        return components

    components = find_components()

    min_path_lengths = {comp_id: paths[0] for comp_id, paths in components.items()}
    max_paths = {comp_id: max(paths) for comp_id, paths in components.items()}

    for path_id in min_path_lengths:
        for comp_id in components:
            if path_id in components[comp_id]:
                min_path_lengths[comp_id] = min(min_path_lengths[comp_id], paths[path_id])
                max_paths[comp_id] = max(max_paths[comp_id], paths[path_id])

    result = 0
    available_rooms = (max(min_path_lengths, key=lambda k: max_paths[k]) - min(min_path_lengths, key=lambda k: max_paths[k]) + 1)
    available_rooms += min(max_paths.values())

    return n - available_rooms

