from math import gcd
from collections import defaultdict

def lcm(x, y):
    return x * y // gcd(x, y)

def solve(n, x, y):
    lcm_all_pairs = set(range(1, n + 1))
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            diff = abs(i - j)
            if min(x, y) <= diff <= max(x, y):
                lcm_all_pairs.discard(diff)
    # Count complete cycles of 4 (S_{xi} = x, S_yi = y, S_{x+y} = x+y, S_x+y = x+y)
    complete_cycles = n // lcm(4, y)
    for i in range(4):
        complete_cycles += n // lcm(4, 4 * i)
    # Count remaining pairs of the 3rd type
    remaining_pairs = n // lcm(3, y) + n // lcm(3, x)
    return len(lcm_all_pairs) + (n // 2 if n % 2 == 0 else 0) + complete_cycles + remaining_pairs

