def find_center(ax, ay, bx, by, cx, cy):
    """
    Calculate the center of a right isosceles triangle with given two points on the axis and two sides parallel to North-South and East-West directions.
    """
    ab = (bx - ax, by - ay)
    bc = (cx - bx, cy - by)
    cd = (ax - cx, ay - cy)

    h = (bx - ax) * (by - ay) + (cy - by) * (ax - cx)
