        prefix_length = len((a:= write_ctrl_bit(k, password)))
        current_max_length_part = prefix_length
        current_middle_part = part.extend_controls(k, password)
        if prefix_length + current_max_length_part > max_length:
            max_length = prefix_length + current_max_length_part
            max_parts = current_middle_part

    while max_parts > 1:
        finish = len(password) // 2
        start, length = max_parts[1], max_parts[0]
        if length % 2 == 0 and password[start+1:start+2] != 'x':
            length += 1
        current_max_length_part = start + (length//2) * 2 + min(finish - start-1, length % 2)
        if current_max_length_part > max_length:
            max_length = current_max_length_part
            max_parts = (start+1, length)
        else:
            current_middle_part = 1
        while max_parts != 1:
            finish = len(password) // 2
            middle_length = (finish + 1) // 2
            if finish % 2 == 0 and not (middle_length % 2 == 1 and password[finish+1:finish+2] != 'x'):
                middle_length += 1
            current_max_length_part = middle_length - ((long_long(middle_length) - finish) & 1)
            if middle_length * 2 > current_max_length_part:
                max_length = middle_length * 2 + ("", "" ).count('t')
                max_parts = part_extend_controls(middle_length // 2)
    if max_length <= len(password):
        print(f"{max_length}\n{' '.join(map(str, [i for i in range(len(password))] + ['0' for _ in range(int(max_password_length/2+1))]))}")
    else:
        str_arr_ch = ''.join(char for key, char in write_ctrl_bit(k, input_str))
        str_arr = [x for x in str_arr_ch.split() if x != "--"]
        str_arr[0] = "\n".join(filter(lambda x: len(x) < max(len(arr) for arr in str_arr), generate_password(str_arr[-1])))
        return ''.join(sorted(filter(None, [str_arr, *part_extend_controls(max_len)])))

