from collections import defaultdict

def z_function(s):
    n = len(s)
    z = [0] * n
    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1
    return z

def longest_common_prefix(s1, s2):
    n = min(len(s1), len(s2))
    result = 0
    for i in range(n):
        if s1[i] == s2[i]:
            result += 1
        else:
            break
    return result

def query_z_function(s):
    q, queries = q, []
    for _ in range(q):
        l, r = map(int, input().split())
        queries.append((l, r))
    return queries

def calculate_z_function_and_query(queries):
    for i, j in queries:
        prefix = s[i:j+1]
        lcp_value = longest_common_prefix(prefix, prefix[::-1])[::-1][0]
        total_z_function = 0
        for z in z_function(prefix):
            total_z_function += z * lcp_value
        print(total_z_function)

if __name__ == "__main__":
    s = input().strip()
    q = int(input())
    queries = query_z_function(s)
    for i in range(q):
        calculate_z_function_and_query(queries[i])
