def beauty(N, A):
    val = 0
    for i in range(1, N):
        for j in range(i + 1, N):
            if A[i] < A[j]:
                val += 1
            else:
                val -= 1
    return val

def expected_bfsgreen(N, edges):
    # Perform BFS for all possible trees
    ans = 0.0
    for i in range(1, N):
        A = sorted([j[i] for j in edges], reverse=True)
        v = beauty(N, A)
        ans += v / len(edges)
    return ans / len(edges)

