from math import gcd
from fractions import Fraction

def find_total_mult(n: int, x: int, y: int) -> int:
    # Function to calculate the number of multiples of a number <= n
    total = n // x - n//y
    if x != y and x < 22 and y < 22:
        return total + (x-1) + (y-1)
    groups = list(range(x-1, 22, x-1))
    total += sum([group // y for group in groups if query.count(group // y) < 2])
    return total + (n // (y * gcd(x,y)))

def query(x1, y1, x2, y2):
    x1 = Fraction(x1, Fraction(y1, 1))
    x2 = Fraction(x2, Fraction(y2, 1))

    if x1 < x2 and x1 >= 1 and x1 <= 10**9:
        return 0

    x1, y1, x2, y2 = map(Fraction, [x1, y1, x2, y2])

    return find_total_mult(int(x1.replace('-','')), int(y1.replace('-','')), int(x2.replace('-', '')))
